package com.accountease;
import jakarta.servlet.FilterChain; import jakarta.servlet.ServletException; import jakarta.servlet.http.*; import java.io.IOException; import org.springframework.context.annotation.*; import org.springframework.http.HttpStatus; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.web.*; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.web.filter.OncePerRequestFilter;
@Configuration public class SecurityConfig {
 @Bean SecurityFilterChain security(HttpSecurity http) throws Exception { return http.csrf(c->c.disable()).authorizeHttpRequests(a->a.requestMatchers("/api/auth/login","/error").permitAll().anyRequest().authenticated()).addFilterBefore(new TokenFilter(),UsernamePasswordAuthenticationFilter.class).build(); }
 static class TokenFilter extends OncePerRequestFilter { protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException { if(req.getRequestURI().equals("/api/auth/login")){chain.doFilter(req,res);return;} String h=req.getHeader("Authorization"); Long owner=h==null||!h.startsWith("Bearer ")||JwtService.ownerId(h.substring(7))==null?null:Long.valueOf(JwtService.ownerId(h.substring(7))); if(owner==null){res.sendError(HttpStatus.UNAUTHORIZED.value(),"Authentication required");return;} req.setAttribute("ownerId",owner); chain.doFilter(req,res); } }
}